from typing import List


class Solution:
    # Function to find articulation points by removing every vertex.
    def articulationPoints(
        self, vertices: int, edges: List[List[int]]
    ) -> List[int]:
        adjacency: List[List[int]] = [[] for _ in range(vertices)]

        # Build the undirected adjacency list once.
        for first, second in edges:
            adjacency[first].append(second)
            adjacency[second].append(first)

        # Function to count components while ignoring one vertex.
        def count_components(removed_vertex: int) -> int:
            visited = [False] * vertices
            components = 0

            # Start traversal from every remaining unvisited vertex.
            for start in range(vertices):
                if start == removed_vertex or visited[start]:
                    continue

                components += 1
                pending = [start]
                visited[start] = True

                while pending:
                    node = pending.pop()

                    for neighbor in adjacency[node]:
                        if neighbor != removed_vertex and not visited[neighbor]:
                            visited[neighbor] = True
                            pending.append(neighbor)

            return components

        original_components = count_components(-1)
        answer: List[int] = []

        # Compare component counts after removing every candidate vertex.
        for removed in range(vertices):
            remaining_components = count_components(removed)
            if remaining_components > original_components:
                answer.append(removed)

        # Return -1 when no articulation point exists.
        return answer if answer else [-1]


# Driver function with a hard-coded undirected graph.
def main() -> None:
    vertices = 7
    edges = [
        [0, 1], [1, 2], [2, 0], [0, 3],
        [3, 4], [4, 5], [5, 3], [5, 6]
    ]

    solution = Solution()
    print(solution.articulationPoints(vertices, edges))


if __name__ == "__main__":
    main()
